(()=>{let edition='one';try{edition=localStorage.getItem('vibe-edition')==='law'?'law':'one';}catch{}function links(){document.querySelectorAll('[data-workspace]').forEach(a=>{a.href='/account/?edition='+edition+'#'+a.dataset.workspace;});document.querySelectorAll('[data-plans]').forEach(a=>a.href='/plans/?edition='+edition);}links();document.querySelectorAll('[data-select]').forEach(a=>a.addEventListener('click',()=>{try{localStorage.setItem('vibe-edition',a.dataset.select);}catch{}}));let saved=false;try{saved=!!localStorage.getItem('vibe-edition');}catch{}if(saved){const name=edition==='law'?'Vibe Law':'Vibe One';document.querySelector('#resume').hidden=false;document.querySelector('#resume-link').href='/space/?edition='+edition;document.querySelector('#resume-link').textContent='Return to '+name+' →';document.querySelector('#current-space').textContent='Last space: '+name;}if(location.hash&&!['#overview','#top'].includes(location.hash))location.replace('/account/?edition='+edition+location.hash);})();